```javascript
const fs = require('fs');

const N = Number(fs.readFileSync(0, 'utf8').trim());
const dp = new Int32Array(N + 1);
dp.fill(1e9);
dp[0] = 0;

for (let i = 1; i <= N; i++) {
  let x = i;
  while (x > 0) {
    const digit = x % 10;
    if (digit !== 0) {
      dp[i] = Math.min(dp[i], dp[i - digit] + 1);
    }
    x = Math.floor(x / 10);
  }
}

console.log(dp[N].toString());
